  <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z08> brick:hasPoint ?pt .
  ?pt rdf:type ?cls .
  OPTIONAL { ?pt rdfs:label ?label }
  OPTIONAL { ?pt ref:hasTimeseriesId ?tsid }
}

